def normalizar_ruts(apps, schema_editor):
    """
    En la EVA2 algunos RUT se guardaron con puntos. Así, "22.222.222-2" y
    "22222222-2" quedaban como pacientes distintos. Aquí se dejan todos sin
    puntos y con la K en mayúscula. Si al normalizar el RUT ya existe en otro
    paciente (un duplicado real), NO se toca: hay que revisarlo a mano.
    """
    Paciente = apps.get_model('hospitalapp', 'Paciente')
    for paciente in Paciente.objects.all():
        normalizado = paciente.rut.strip().replace('.', '').upper()
        if normalizado == paciente.rut:
            continue
        duplicado = Paciente.objects.filter(rut=normalizado).exclude(id=paciente.id).exists()
        if duplicado:
            print(f"\n  AVISO: el RUT {paciente.rut} (id {paciente.id}) está duplicado; revísalo a mano.")
            continue
        paciente.rut = normalizado
        paciente.save(update_fields=['rut'])


